sqlGroup.select:
select a.id, b.`name` as contactName, b.mobile_phone, c.`name` as accName, d.`name` as oppName, a.type, a.manager_read, date_format(a.created_time,'%Y-%m-%d %H:%i:%s') as created_time, cs.`name` AS createdStaffName, a.submit_status, date_format(a.checkin_time,'%Y-%m-%d %H:%i:%s') as checkin_time, a.checkin_address, a.created_staff_id
from jml_sales_report a left join jml_contact b on a.contact_id = b.id left join jml_account c on a.account_id = c.id left join jml_opportunity d on a.opportunity_id = d.id left join jml_staff cs ON a.created_staff_id = cs.id
and a.created_staff_id = #{staffId}
and a.created_staff_id = #{createdStaffId}
and a.submit_status='1'
and a.created_staff_id = #{createdStaffId}
and a.manager_read = '0' and a.submit_status='1'
and a.created_staff_id = #{createdStaffId}
and a.checkin_time >= str_to_date(#{startDate},'%Y-%m-%d')
and a.checkin_time <= date_add(str_to_date(#{endDate},'%Y-%m-%d'),interval 1 day)
and a.arrival_time >= str_to_date(#{startDate},'%Y-%m-%d')
and a.arrival_time <= date_add(str_to_date(#{endDate},'%Y-%m-%d'),interval 1 day)
and (b.name like '%${multiFiled}%' or c.name like '%${multiFiled}%' or cs.name like '%${multiFiled}%')
and a.account_id = #{accountId}
and a.contact_id = #{contactId}
and a.opportunity_id = #{oppId}
and a.reimbursement_id = #{reimId}
and a.manager_read = '0'
order by a.submit_status asc,a.created_time desc,a.arrival_time desc

sqlGroup.update:
update jml_sales_report a set a.reimbursement_id = #{reimId}, a.update_staff_id =#{staffId}
a.id in
#{rid}

sqlGroup.select:
SELECT cs.NAME AS staffName, cs.id as staffId,
IFNULL(count( CASE WHEN DATE_FORMAT( a.arrival_time, '%Y-%m-%d' ) = #{i.arrival_time} THEN a.id END ), 0 ) AS #{i.arrival_time}
IFNULL(count( CASE WHEN DATE_FORMAT( a.checkin_time, '%Y-%m-%d' ) = #{i.arrival_time} THEN a.id END ), 0 ) AS #{i.arrival_time}
FROM jml_sales_report a LEFT JOIN jml_staff cs ON a.created_staff_id = cs.id
and cs.name like '%${multiFiled}%'
and a.submit_status = '1'
and DATE_FORMAT(a.arrival_time,'%Y-%m-%d') between #{startDate} and #{endDate}
and DATE_FORMAT(a.arrival_time,'%Y-%m-%d') between DATE_FORMAT(NOW() - INTERVAL WEEKDAY(NOW()) DAY, '%Y-%m-%d') and DATE_FORMAT(NOW() + INTERVAL (6 - WEEKDAY(NOW())) DAY, '%Y-%m-%d')
and (a.account_id is not null or a.account_id !='') and a.submit_status = '1'
and DATE_FORMAT(a.arrival_time,'%Y-%m-%d') between #{startDate} and #{endDate}
and DATE_FORMAT(a.arrival_time,'%Y-%m-%d') between DATE_FORMAT(NOW() - INTERVAL WEEKDAY(NOW()) DAY, '%Y-%m-%d') and DATE_FORMAT(NOW() + INTERVAL (6 - WEEKDAY(NOW())) DAY, '%Y-%m-%d')
and a.checkin_time IS NOT NULL
and DATE_FORMAT(a.checkin_time,'%Y-%m-%d') between #{startDate} and #{endDate}
and DATE_FORMAT(a.checkin_time,'%Y-%m-%d') between DATE_FORMAT(NOW() - INTERVAL WEEKDAY(NOW()) DAY, '%Y-%m-%d') and DATE_FORMAT(NOW() + INTERVAL (6 - WEEKDAY(NOW())) DAY, '%Y-%m-%d')
GROUP BY a.created_staff_id
